import{z as o,x as i,o as B,c as C,q as t,j as n,D as e,d as a,s,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"团队流程与案例","description":"","frontmatter":{"title":"团队流程与案例","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sl-team-cases.md","filePath":"quant/sl-team-cases.md","lastUpdated":1791413859000}'),d={name:"quant/sl-team-cases.md"};function D(p,E,m,c,h,u){const r=i("Mermaid");return B(),C("div",null,[E[2]||(E[2]=t('<h1 id="团队流程与案例" tabindex="-1">团队流程与案例 <a class="header-anchor" href="#团队流程与案例" aria-label="Permalink to &quot;团队流程与案例&quot;">​</a></h1><div class="epigraph"><p>治理最终写在岗位与会议节奏里：谁在哪个阶段有一票、多久复审一次、超时升级到谁——流程没有载体，就只是一堆文档。</p><footer>—— 据 Federal Reserve SR 11-7 的治理原则整理</footer></div><p><a href="/quant/sl-knowledge-management">上一课</a>把生命周期的沉淀变成可检索的卷宗。至此规则都在了——台账、版本、容量、衰减、合规、退出、知识——本课写让规则跑起来的东西：角色怎么切、会议怎么开、升级怎么走，然后让三个综合案例把全流程走一遍。本课也是收束前的彩排：看完这三个案例，前八课的接口应该全部对上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规则清楚而流程失灵的样子，每个团队都见过几种。批准找不到人：唯一有签字权的 owner 休假，新版本冻在评审站一周。报警无人处置：监测软带报警发进群，没人知道自己有没有处置权，也没有处置时限。复盘会开成追责会：从此没人把真死因写进卷宗，失败库静悄悄腐烂。三者共同的缺口：每条规则没有绑定到<strong>岗位、节奏与升级路径</strong>。规则说「穿预算带降杠杆」，流程必须回答「谁执行、几小时内、不执行会怎样」。</p><p><span class="marginnote">直觉类比：规则没绑岗位，就像消防预案写满了步骤、却没写谁拿灭火器——真着火时人人都在等别人先动。岗位、时限与默认动作，把「应该有人做」变成「这个人必须在几小时内做，不做系统就自动降杠杆」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>角色最小集六种：研究（提案与假设）、组合管理（配置与扩容请求）、独立风险（判据复算、监测 owner、停机预授权）、执行（硬限制与清仓）、合规（门与记录）、台账管理员——最后一项通常是风险团队内的一个职能。节奏三档：周度监测例会，只读台账出报表；月度容量与衰减复审；季度合规再声明与版本有效期复审。升级路径预写并配<strong>默认动作</strong>：硬触发自动执行，不需升级；软带边缘给 owner 限时决策窗；超时按预写默认降杠杆——把「不作为」变成有成本的选择。每个台账字段挂一行「谁写、谁审、谁读」，空字段的岗位即暴露流程缺口。</p><p><span class="marginnote">术语翻译：升级路径就是「这件事处理不了时找谁、找多快」的预写清单；默认动作是超时后系统自动执行的动作。二者合起来消灭「没人拍板」这个状态——拍板人不在，预案替他拍，而且全程留痕。</span></p>',9)),(B(),n(l,null,{default:e(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALERT%5B%22%E8%BD%AF%E5%B8%A6%E6%8A%A5%E8%AD%A6%22%5D%20--%3E%20OWNER%5B%22%E9%A3%8E%E9%99%A9%20owner%20%E9%99%90%E6%97%B6%E5%86%B3%E7%AD%96%22%5D%0A%20%20OWNER%20--%3E%20ACT%5B%22%E9%A2%84%E5%86%99%E5%8A%A8%E4%BD%9C%EF%BC%9A%E9%99%8D%E6%9D%A0%E6%9D%86%E6%88%96%E7%BB%B4%E6%8C%81%E5%B9%B6%E8%AE%B0%E5%BD%95%22%5D%0A%20%20OWNER%20--%3E%7C%E8%B6%85%E6%97%B6%7C%20DEFAULT%5B%22%E9%BB%98%E8%AE%A4%E5%8A%A8%E4%BD%9C%EF%BC%9A%E9%99%8D%E6%9D%A0%E6%9D%86%22%5D%0A%20%20HARD%5B%22%E7%A1%AC%E8%A7%A6%E5%8F%91%22%5D%20--%3E%20AUTO%5B%22%E8%87%AA%E5%8A%A8%E6%89%A7%E8%A1%8C%EF%BC%9A%E5%81%9C%E6%9C%BA%E4%B8%8E%E5%86%BB%E7%BB%93%EF%BC%8C%E4%B8%8D%E9%9C%80%E5%8D%87%E7%BA%A7%22%5D%0A%20%20ACT%20--%3E%20CADENCE%5B%22%E5%91%A8%E5%BA%A6%E4%BE%8B%E4%BC%9A%E4%B8%8E%E6%9C%88%E5%BA%A6%E5%A4%8D%E5%AE%A1%EF%BC%9A%E5%8F%AA%E8%AF%BB%E5%8F%B0%E8%B4%A6%E5%87%BA%E6%8A%A5%E8%A1%A8%22%5D%0A%20%20AUTO%20--%3E%20CADENCE%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("三个综合案例（综合自常见模式，非真实机构）。"),A("strong",null,"案例一，拥挤降档"),a("：月度复审发现某策略与已部署池的滚动相关穿拥挤预算带——容量与衰减共用这条带——软带预授权降杠杆三成；下周监测例会确认衰减带同步走边；死因鉴别判拥挤成立，处置是新版本缩宇宙、加拥挤惩罚重走台阶，而不是直接退役。"),A("strong",null,"案例二，合规事件门"),a("：执行参数改动让报撤比外观越限——没有人事先送审，因为「只是执行侧改动」；事件门触发重审，处置是硬限制收紧进订单网关、版本升版、缺送的记录补全，合规字段的变更全程留痕。"),A("strong",null,"案例三，执行漂移"),a("：穿带停机工单生成后，死因鉴别发现 IC 稳定而实施缺口扩大——alpha 没死，执行漂了；处置落在执行侧配置的新版本上，信号版本不动，恢复后 \\(N\\) 不清零。")],-1)),(B(),n(l,null,{default:e(()=>[s(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E6%A1%88%E4%BE%8B%E4%B8%80%EF%BC%9A%E6%8B%A5%E6%8C%A4%E7%9B%B8%E5%85%B3%E7%A9%BF%E5%B8%A6%22%5D%20--%3E%20D1%5B%22%E7%BC%A9%E5%AE%87%E5%AE%99%E5%8A%A0%E6%8B%A5%E6%8C%A4%E6%83%A9%E7%BD%9A%EF%BC%9A%E6%96%B0%E7%89%88%E6%9C%AC%E9%87%8D%E8%B5%B0%E5%8F%B0%E9%98%B6%22%5D%0A%20%20C2%5B%22%E6%A1%88%E4%BE%8B%E4%BA%8C%EF%BC%9A%E6%8A%A5%E6%92%A4%E6%AF%94%E5%A4%96%E8%A7%82%E8%B6%8A%E9%99%90%22%5D%20--%3E%20D2%5B%22%E4%BA%8B%E4%BB%B6%E9%97%A8%E9%87%8D%E5%AE%A1%EF%BC%9A%E7%A1%AC%E9%99%90%E5%88%B6%E6%94%B6%E7%B4%A7%E8%BF%9B%E8%AE%A2%E5%8D%95%E7%BD%91%E5%85%B3%22%5D%0A%20%20C3%5B%22%E6%A1%88%E4%BE%8B%E4%B8%89%EF%BC%9AIC%20%E7%A8%B3%E5%AE%9A%E8%80%8C%E7%BC%BA%E5%8F%A3%E6%89%A9%E5%A4%A7%22%5D%20--%3E%20D3%5B%22%E6%89%A7%E8%A1%8C%E4%BE%A7%E6%96%B0%E7%89%88%E6%9C%AC%EF%BC%9A%E4%BF%A1%E5%8F%B7%E7%89%88%E6%9C%AC%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20D1%20--%3E%20NKEEP%5B%22N%20%E4%B8%8D%E6%B8%85%E9%9B%B6%EF%BC%9A%E6%81%A2%E5%A4%8D%E5%90%8E%E7%BB%A7%E7%BB%AD%E7%B4%AF%E8%AE%A1%22%5D%0A%20%20D2%20--%3E%20NKEEP%0A%20%20D3%20--%3E%20NKEEP%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">最小组织的红线只有一条：判据复算与监测 owner 不得由提案人兼任。其余角色都可以合并，这条合并不了——激励独立是有效挑战的底座（SR 11-7）。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>委员会不是治理本身：会议只处理台账无法自动化的判断——跨策略权衡、灰区裁量、带外特例；凡能预写的都应预写在台账与状态机里，会议室不做统计。流程重则无人报真话：追责导向的升级路径会系统性扭曲 \\(N\\) 与死因记录，<a href="/quant/research-postmortem">复盘免责</a>同样适用于运行事件——只追流程缺口，不追如实上报的人。小团队可以一人多角，但独立复核与监测 owner 的红线不松；六个角色是为职责建模，不是为编制建模。三个案例是教学模式下的典型路径，真实事件的分叉远多于此，判据与状态机才是处理分叉的依据。</p><p><span class="marginnote">常见误区：初学者容易把复盘会开成追责会，以为罚得越狠越安全。实际效果是没人再写真死因，失败库静悄悄腐烂，下一个团队把钱花在同一口井上。只追流程缺口、不追如实上报的人，账才记得下去。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每条规则绑定岗位、节奏与升级路径；台账字段挂「谁写、谁审、谁读」，空岗即缺口。</li><li>升级路径配预写默认动作：软带给时限，超时降杠杆；硬触发自动执行不进会议室。</li><li>案例表明三类处置走不同的门：拥挤走版本重审、执行改动走事件门、执行漂移修执行侧。</li><li>独立复核与监测 owner 不得兼任提案人，激励独立是流程红线的底线。</li><li>出处：治理原则与有效挑战据 Federal Reserve SR 11-7（2011）整理；案例涉及的机制分别见<a href="/quant/sl-capacity-governance">容量治理</a>、<a href="/quant/sl-decay-governance">衰减治理</a>、<a href="/quant/sl-compliance-review">合规审查</a>与<a href="/quant/research-postmortem">研究复盘</a>。</li></ul>',6))])}const _=o(d,[["render",D]]);export{F as __pageData,_ as default};
